// Per-column sum. To keep the inner loop walking contiguous memory (good
// for L1), we iterate in row-major order and accumulate each element into
// the corresponding column bucket. Consecutive `c` accesses are
// `data_[r * cols_ + c]` and `data_[r * cols_ + c + 1]`, i.e. stride 1.
std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    for (std::size_t r = 0; r < rows_; ++r) {
        const std::size_t base = r * cols_;
        for (std::size_t c = 0; c < cols_; ++c) {
            result[c] += data_[base + c];
        }
    }
    return result;
}

// Per-column sum. To keep the inner loop walking contiguous memory (good
